import java.io.IOException;
import java.util.Locale;

import org.eclipse.rdf4j.common.annotation.InternalUseOnly;
import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.rio.helpers.NTriplesUtil;

/** Writes resource terms without letting their labels alter a result row's structure. */
@InternalUseOnly
public final class SPARQLResultResourceWriter {
	private static final String ENCODED_BNODE_PREFIX = "rdf4jEsc";

	private SPARQLResultResourceWriter() {
	}

	/** Writes an IRIREF, retaining the original IRI through Unicode escapes. */
	public static void appendIRI(IRI iri, Appendable out) throws IOException {
		out.append('<');
		appendIRIContent(iri, out);
		out.append('>');
	}

	/** Writes the IRI body used by CSV triple terms, whose resource syntax omits angle brackets. */
	public static void appendIRIContent(IRI iri, Appendable out) throws IOException {
		String value = iri.stringValue();
		for (int offset = 0; offset < value.length();) {
			int codePoint = value.codePointAt(offset);
			if (codePoint >= Character.MIN_SURROGATE && codePoint <= Character.MAX_SURROGATE) {
				throw new IllegalArgumentException("IRI contains an unpaired surrogate");
			}
			if (needsEscape(codePoint)) {
				appendUnicodeEscape(codePoint, out);
			} else {
				out.append(value, offset, offset + Character.charCount(codePoint));
			}
			offset += Character.charCount(codePoint);
		}
	}

	/** Writes a legal blank-node label without aliasing distinct input IDs. */
	public static void appendBNode(BNode node, Appendable out) throws IOException {
		String id = node.getID();
		out.append("_:");
		if (!id.startsWith(ENCODED_BNODE_PREFIX) && NTriplesUtil.BNODE_PATTERN.matcher("_:" + id).matches()) {
			out.append(id);
			return;
		}

		// Reserve the prefix even for already-legal IDs. The UTF-16 encoding is injective for every Java String.
		out.append(ENCODED_BNODE_PREFIX);
		for (int i = 0; i < id.length(); i++) {
			char c = id.charAt(i);
			for (int shift = 12; shift >= 0; shift -= 4) {
				out.append(Character.forDigit((c >>> shift) & 0xF, 16));
			}
		}
	}

	private static boolean needsEscape(int codePoint) {
		return codePoint <= 0x20 || Character.isISOControl(codePoint) || Character.isWhitespace(codePoint)
				|| Character.isSpaceChar(codePoint)
				|| "<>\"{}|^`\\".indexOf(codePoint) >= 0;
	}

	private static void appendUnicodeEscape(int codePoint, Appendable out) throws IOException {
		int width = codePoint <= 0xFFFF ? 4 : 8;
		String hex = Integer.toHexString(codePoint).toUpperCase(Locale.ROOT);
		out.append(width == 4 ? "\\u" : "\\U");
		for (int i = hex.length(); i < width; i++) {
			out.append('0');
		}
		out.append(hex);
	}
}
